"""Generates solana-onion-relay-service-v3/serve.mjs from the qualified v2 service by exact-match patches (each asserted to match exactly once).
v3 differs from v2 in three things only: it takes the task from ../solana-relay-cleanup-v1 (so a settled payment is followed by the closing of the verifier receipt
and of the proof buffer, returning their rent to the sponsor), it pins that setting (CLEANUP=true) in the file like every other operator setting, and it prints one
`cleanup` event per change of the cleanup phase so a run shows which account was given back and when. Nothing else about the service changes.
usage: make_service.py (once; refuses to overwrite)"""
import difflib
from pathlib import Path
HERE=Path(__file__).resolve().parent;WORK=HERE.parent
SRC=WORK/'solana-onion-relay-service-v2/serve.mjs';OUT=HERE/'serve.mjs'
assert not OUT.exists(),'refusing to overwrite serve.mjs'
text=SRC.read_text()
PAIRS=[
 ("// WINDOWED revision of ../solana-onion-relay-service-v1/serve.mjs (frozen, untouched): the same composition, but the task, the repository, the funding and\n// the publication sender are the windowed ones of ../solana-relay-windowed-v1, and the proof buffer is filled WINDOW chunk uploads at a time.\n",
  "// CLEANUP revision of ../solana-onion-relay-service-v2/serve.mjs (qualified, untouched), itself the WINDOWED revision of ../solana-onion-relay-service-v1/serve.mjs.\n// The task is the one of ../solana-relay-cleanup-v1: after the pool has settled a payment the relay closes the verifier receipt and then the proof buffer it created\n// for that request, so their rent returns to the sponsor. Generated by make_service.py; the whole difference from v2 is that file.\n// WINDOWED revision of ../solana-onion-relay-service-v1/serve.mjs (frozen, untouched): the same composition, but the task, the repository, the funding and\n// the publication sender are the windowed ones of ../solana-relay-windowed-v1, and the proof buffer is filled WINDOW chunk uploads at a time.\n"),
 ("import {LocalRelayTask} from '../solana-relay-windowed-v1/relay-task.mjs';\nimport {RelayRepository} from '../solana-relay-windowed-v1/relay-repository.mjs';\n",
  "import {LocalRelayTask} from '../solana-relay-cleanup-v1/relay-task.mjs';\nimport {RelayRepository} from '../solana-relay-cleanup-v1/relay-repository.mjs';\n"),
 ("const WINDOW=64;\n","const WINDOW=64;\n// After a settled payment, give the rent of the receipt and of the proof buffer back to the sponsor. Pinned by this file's hash.\nconst CLEANUP=true;\n"),
 ("    repository:repo,validator,verifyProof,signal,fetchImpl,funding:FUNDING,window:WINDOW});\n","    repository:repo,validator,verifyProof,signal,fetchImpl,funding:FUNDING,window:WINDOW,cleanup:CLEANUP});\n"),
 ("    async step(){try{return await task.step();}catch(error){dumpDiagnostics(task.id);throw error;}},\n",
  "    async step(){try{const result=await task.step();if(result.phase==='cleanup')noteCleanup(task.id,result);return result;}catch(error){dumpDiagnostics(task.id);throw error;}},\n"),
 ("async function openTask(raw,signal) {\n",
  "// One line per change of the cleanup phase: which close is being confirmed and in which state.\nlet lastCleanup=null;\nfunction noteCleanup(id,result) {\n  const key=id+'|'+result.step+'|'+result.state;if(key===lastCleanup)return;lastCleanup=key;\n  emit({type:'cleanup',id,step:result.step??null,state:result.state});\n}\nasync function openTask(raw,signal) {\n"),
 ("emit({type:'ready',port,authority,recovered,scope:'local-onion-relay-service',window:WINDOW});","emit({type:'ready',port,authority,recovered,scope:'local-onion-relay-service',window:WINDOW,cleanup:CLEANUP});"),
]
new=text
for old,rep in PAIRS:
    assert new.count(old)==1,(old[:80],new.count(old))
    new=new.replace(old,rep)
OUT.write_text(new)
(HERE/'serve.mjs.diff').write_text(''.join(difflib.unified_diff(text.splitlines(True),new.splitlines(True),'solana-onion-relay-service-v2/serve.mjs','solana-onion-relay-service-v3/serve.mjs')))
print('written',OUT.name,len(new),'bytes')
